def now_utc() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()

def sha256_bytes(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()

def sha256_file(path: Path, chunk: int=8*1024*1024) -> str:
    h=hashlib.sha256()
    with path.open("rb") as fh:
        while True:
            block=fh.read(chunk)
            if not block: break
            h.update(block)
    return h.hexdigest()

def ensure_regular(path: Path) -> None:
    if not path.is_file() or path.is_symlink():
        raise UpdateError(f"required regular file missing/invalid: {path}")

def asset(name: str) -> bytes:
    try: payload=zlib.decompress(base64.b64decode(ASSET_DATA[name]))
    except Exception as exc: raise UpdateError(f"asset decode failed: {name}") from exc
    if sha256_bytes(payload)!=ASSET_HASHES[name]:
        raise UpdateError(f"embedded asset SHA mismatch: {name}")
    return payload

def atomic_write(path: Path, payload: bytes, mode: int|None=None) -> None:
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,name=tempfile.mkstemp(prefix="."+path.name+".",suffix=".part",dir=str(path.parent))
    try:
        with os.fdopen(fd,"wb") as fh:
            fh.write(payload); fh.flush(); os.fsync(fh.fileno())
        if mode is not None: os.chmod(name,mode)
        os.replace(name,path)
    finally:
        if os.path.exists(name): os.unlink(name)

def write_tsv(path: Path, rows: list[dict[str,Any]], fields: list[str]) -> None:
    sio=io.StringIO();w=csv.DictWriter(sio,delimiter="\t",fieldnames=fields,extrasaction="ignore",lineterminator="\n")
    w.writeheader();w.writerows(rows);atomic_write(path,sio.getvalue().encode())

def write_metrics(path: Path, items: list[tuple[str,Any]]) -> None:
    write_tsv(path,[{"metric":k,"value":v} for k,v in items],["metric","value"])

def read_metrics_bytes(raw: bytes) -> dict[str,str]:
    return {r["metric"]:r["value"] for r in csv.DictReader(io.StringIO(raw.decode()),delimiter="\t")}

def safe_member(member: tarfile.TarInfo) -> bool:
    p=Path(member.name)
    return not p.is_absolute() and ".." not in p.parts and not member.issym() and not member.islnk() and (member.isfile() or member.isdir())

def verify_manifest_tar(path: Path, expected_sha: str|None=None, require_sidecar: bool=True) -> dict[str,Any]:
    ensure_regular(path); actual=sha256_file(path)
    if expected_sha and actual!=expected_sha: raise UpdateError(f"bundle SHA mismatch: {path}: {actual} != {expected_sha}")
    if require_sidecar:
        side=Path(str(path)+".sha256");ensure_regular(side)
        tokens=side.read_text(encoding="utf-8").strip().split()
        if not tokens or tokens[0]!=actual: raise UpdateError(f"bundle sidecar mismatch: {path}")
    with tarfile.open(path,"r:gz") as tf:
        members=tf.getmembers()
        if any(not safe_member(m) for m in members): raise UpdateError(f"unsafe bundle member: {path}")
        if len({m.name for m in members})!=len(members): raise UpdateError(f"duplicate bundle member: {path}")
        files={m.name:m for m in members if m.isfile()}
        manifests=[m for m in members if m.isfile() and m.name.endswith("/artifact_manifest.tsv")]
        if len(manifests)!=1: raise UpdateError(f"artifact manifest multiplicity mismatch: {path}: {len(manifests)}")
        manifest=manifests[0];prefix=manifest.name.rsplit("/",1)[0]
        rows=list(csv.DictReader(io.StringIO(tf.extractfile(manifest).read().decode()),delimiter="\t"))
        if not rows: raise UpdateError(f"empty artifact manifest: {path}")
        path_field="path" if "path" in rows[0] else ("relative_path" if "relative_path" in rows[0] else None)
        if path_field is None: raise UpdateError(f"unsupported artifact manifest path field: {path}")
        expected={f"{prefix}/{r[path_field]}" for r in rows};actual_names=set(files)-{manifest.name}
        if expected!=actual_names: raise UpdateError(f"artifact manifest coverage mismatch: {path}")
        for row in rows:
            rel=row[path_field];m=files[f"{prefix}/{rel}"];raw=tf.extractfile(m).read()
            if len(raw)!=int(row["bytes"]) or sha256_bytes(raw)!=row["sha256"]:
                raise UpdateError(f"artifact manifest mismatch: {path}: {rel}")
    return {"path":str(path),"bytes":path.stat().st_size,"sha256":actual,"members":len(members),"manifest_rows":len(rows),"status":"PASS"}

def make_manifest(root: Path) -> None:
    rows=[]
    for p in sorted(root.rglob("*")):
        if not p.is_file() or p.name=="artifact_manifest.tsv": continue
        rows.append({"path":p.relative_to(root).as_posix(),"bytes":p.stat().st_size,"sha256":sha256_file(p)})
    write_tsv(root/"artifact_manifest.tsv",rows,["path","bytes","sha256"])

def make_bundle(root: Path, output: Path) -> str:
    side=Path(str(output)+".sha256")
    if output.exists() or side.exists(): raise UpdateError(f"refusing to overwrite bundle: {output}")
    with tarfile.open(output,"w:gz") as tf: tf.add(root,arcname=root.name,recursive=True)
    digest=sha256_file(output);side.write_text(f"{digest}  {output.name}\n",encoding="utf-8");return digest

def current_updater_sha() -> str:
    return sha256_file(Path(__file__).resolve())

def source_insertion(updater_sha: str) -> str:
    text=asset("insertion_template.txt").decode()
    if text.count(PLACEHOLDER)<2: raise UpdateError("source insertion placeholder multiplicity invalid")
    text=text.replace(PLACEHOLDER,updater_sha)
    if PLACEHOLDER in text: raise UpdateError("source insertion placeholder remains")
    return text

def promotion_plan_bytes(updater_sha: str) -> bytes:
    plan=json.loads(asset("promotion_plan.json"))
    found=0
    for row in plan.get("explicit_implementations",[]):
        if row.get("implementation_id")=="impl_stage15n_generic_active_path_promotion_v0_1_0":
            if row.get("script_sha256")!="__UPDATER_SHA256__":
                raise UpdateError("promotion-plan updater placeholder mismatch")
            row["script_sha256"]=updater_sha
            found+=1
    if found!=1: raise UpdateError("promotion-plan updater row multiplicity mismatch")
    plan["updater_sha256"]=updater_sha
    return (json.dumps(plan,indent=2,sort_keys=True)+"\n").encode()

def patch_ssot_source(source: str, insertion: str) -> str:
    if SOURCE_MARKER in source: raise UpdateError("Stage15N source marker already present")
    if source.count(LEGACY_VALIDATION_BLOCK_1)!=1 or source.count(LEGACY_VALIDATION_BLOCK_2)!=1:
        raise UpdateError("SSOT validation baseline block mismatch")
    source=source.replace(LEGACY_VALIDATION_BLOCK_1,GENERIC_VALIDATION_BLOCK_1,1)
    source=source.replace(LEGACY_VALIDATION_BLOCK_2,GENERIC_VALIDATION_BLOCK_2,1)
    if source.count(INSERTION_ANCHOR)!=1: raise UpdateError("SSOT insertion anchor mismatch")
    source=source.replace(INSERTION_ANCHOR,textwrap.indent(insertion,"    ")+"\n\n"+INSERTION_ANCHOR,1)
    compile(source,"<rnatr_ssot_stage15n_proposed>","exec")
    return source

def ssot_command(paths: Paths, action: str) -> list[str]:
    command=[sys.executable,str(paths.ssot_cli),"--project-root",str(paths.project_root)]
    if paths.project_root.resolve()!=Path("/mnt/intelssd/rnatr_project"):
        command.append("--allow-nonstandard-root")
    command.append(action)
    return command

def verify_baseline(paths: Paths, check_targets_absent: bool=True) -> tuple[list[dict[str,Any]],list[dict[str,Any]]]:
    rows=[]
    for rel,expected in BASELINE_GUARDS.items():
        p=paths.project_root/rel;ensure_regular(p);actual=sha256_file(p);status="PASS" if actual==expected else "FAIL"
        rows.append({"artifact":rel,"path":str(p),"expected_sha256":expected,"actual_sha256":actual,"status":status})
        if status!="PASS": raise UpdateError(f"baseline drift: {p}")
    if SOURCE_MARKER in paths.ssot_cli.read_text(encoding="utf-8"): raise UpdateError("Stage15N marker already installed")
    db=sqlite3.connect(paths.ssot_db);db.row_factory=sqlite3.Row
    try:
        integrity=db.execute("pragma integrity_check").fetchone()[0];fk=len(db.execute("pragma foreign_key_check").fetchall())
        pipeline=[dict(r) for r in db.execute("select * from current_pipeline")]
        active=db.execute("select count(*) from implementations where lifecycle_status='ACTIVE'").fetchone()[0]
        discovered=db.execute("select count(*) from implementations where lifecycle_status='DISCOVERED'").fetchone()[0]
    finally: db.close()
    if integrity!="ok" or fk or len(pipeline)!=11 or active!=11 or discovered!=0:
        raise UpdateError(f"baseline SSOT semantic mismatch: integrity={integrity} fk={fk} pipeline={len(pipeline)} active={active} discovered={discovered}")
    proc=subprocess.run(ssot_command(paths,"validate"),text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if proc.returncode!=0: raise UpdateError("baseline SSOT validate failed: "+(proc.stdout+proc.stderr)[-2000:])
    bundles=[]
    for name,expected in BUNDLE_GUARDS.items(): bundles.append(verify_manifest_tar(paths.downloads/name,expected))
    if check_targets_absent:
        occupied=[str(p) for p in paths.targets().values() if p.exists()]
        if paths.qc_root.exists() or paths.metadata_root.exists(): occupied += [str(paths.qc_root),str(paths.metadata_root)]
        if occupied: raise UpdateError(f"Stage15N targets are not unused: {occupied}")
    return rows,bundles

def verify_resource_dependencies(paths: Paths) -> list[dict[str,Any]]:
    manifest=json.loads(asset("resource_manifest.json"))
    rows=[]
    for section in ("components","catalogs"):
        for role,entry in sorted(manifest[section].items()):
            rel=Path(entry["relative_path"])
            if rel.is_absolute() or ".." in rel.parts: raise UpdateError(f"unsafe resource path: {section}:{role}")
            p=paths.project_root/rel;ensure_regular(p);actual=sha256_file(p);status="PASS" if actual==entry["sha256"] else "FAIL"
