def verify_preflight(paths: Paths, expected_sha: str) -> dict[str,str]:
    info=verify_manifest_tar(paths.preflight_bundle,expected_sha);updater=Path(__file__).resolve().read_bytes();updater_sha=sha256_bytes(updater)
