        def one(suffix):
            matches=[m for m in members if m.isfile() and m.name.endswith(suffix)]
            if len(matches)!=1: raise UpdateError(f"preflight member multiplicity {suffix}: {len(matches)}")
            return tf.extractfile(matches[0]).read()
