def restore_backup(paths: Paths, backup: Path, state: dict[str,Any]) -> None:
    for rel,existed in state["files"].items():
        p=paths.project_root/rel;source=backup/"files"/rel
        if existed: p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,p)
        elif p.exists(): p.unlink()
    for rel,existed in state["dirs"].items():
        p=paths.project_root/rel
        if not existed and p.exists():
            if p.is_dir() and not p.is_symlink(): shutil.rmtree(p)
            else: p.unlink()
    keep=set(state["backups_before"]);keep.add(backup.name)
    for p in paths.backup_root.iterdir():
        if p.name not in keep:
            if p.is_dir(): shutil.rmtree(p)
            else: p.unlink()

